import { useEffect, useState } from "react";
import getContract from "../utils/getVotingContract";

function VotingPage() {
  const [candidates, setCandidates] = useState([]);
  const [hasVoted, setHasVoted] = useState(false);
  const [account, setAccount] = useState("");
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadVotingData();

    // Reload page when MetaMask account is changed
    if (window.ethereum) {
      window.ethereum.on("accountsChanged", () => {
        window.location.reload();
      });
    }
  }, []);

  const loadVotingData = async () => {
    try {
      const contract = await getContract();
      const accounts = await window.ethereum.request({ method: 'eth_requestAccounts' });
      const userAddress = accounts[0];
      setAccount(userAddress);

      // Check if user has voted
      const voted = await contract.hasUserVoted(userAddress);
      setHasVoted(voted);

      // Get all candidates
      const count = await contract.getCandidateCount();
      const candidatesList = [];

      for (let i = 0; i < count; i++) {
        const name = await contract.getCandidateName(i);
        candidatesList.push({ id: i, name });
      }

      setCandidates(candidatesList);
    } catch (error) {
      console.error("Error loading voting data:", error);
      alert("Failed to load voting data!");
    } finally {
      setLoading(false);
    }
  };

  const handleVote = async (id) => {
    try {
      const contract = await getContract();
      const tx = await contract.vote(id);
      await tx.wait();
      alert("Voted successfully!");
      setHasVoted(true);
    } catch (error) {
      console.error("Vote failed:", error);
      alert("Voting failed. Please try again.");
    }
  };

  const handleReset = async () => {
    try {
      // This would require a reset function in your contract
      const contract = await getContract();
      const tx = await contract.resetVote();
      await tx.wait();
      alert("Vote reset successfully!");
      setHasVoted(false);
    } catch (error) {
      console.error("Reset failed:", error);
      alert("Reset failed. Please try again.");
    }
  };

  if (loading) {
    return <div className="loading-container">Loading...</div>;
  }

  return (
    <div className="voting-container">
      <h2>Welcome: {account}</h2>
      <h3>{hasVoted ? "You have already voted." : "Please cast your vote"}</h3>
      
      <div className="candidates-list">
        {candidates.map((candidate) => (
          <div key={candidate.id} className="candidate-row">
            <span className="candidate-name">{candidate.name}</span>
            {!hasVoted ? (
              <button 
                className="vote-button"
                onClick={() => handleVote(candidate.id)}
              >
                Vote
              </button>
            ) : (
              <button className="voted-button" disabled>
                Voted
              </button>
            )}
          </div>
        ))}
      </div>
      
      {hasVoted && (
        <div className="reset-section">
          <button 
            className="reset-button"
            onClick={handleReset}
          >
            Reset
          </button>
        </div>
      )}
    </div>
  );
}

export default VotingPage;
